      if (posFixedMarker) { map.removeLayer(posFixedMarker); }
      posFixedMarker = L.marker(ll, { icon: livePosIcon("red"), interactive: false, keyboard: false, zIndexOffset: 1000 }).addTo(map);
      map.setView(ll, Math.max(map.getZoom() || 0, 14));
