    MAX_ZOOM: MAX_ZOOM, X_MARK_SVG: X_MARK_SVG,
    baseUrlFor: baseUrlFor, closeDropdowns: closeDropdowns, createModal: createModal,
    detailedPlaceName: detailedPlaceName, escapeHtml: escapeHtml, ico: ico,
    labelsMode: labelsMode, labelsSupported: labelsSupported, modalConfirm: modalConfirm,
