      { m: "rare", sym: "◉", txt: t("status.rare"), st: function () { return detRareFilter; } },
      { m: "year", sym: "🟠", txt: t("status.year", { year: curYear() }), st: function () { return detYearFilter; } },
      { m: "life", sym: "🟡", txt: t("status.life"), st: function () { return detLifeFilter; } },
      { m: "alert", sym: "!", txt: t("status.alert"), st: function () { return detAlertFilter; } }
