    if (which === "hs") return { min: 3, max: 17, get: hotspotZoomFrom, key: "hotspotZoom" };
    if (which === "best") return { min: 3, max: 17, get: bestSiteZoomFrom, key: "bestSiteZoom" };
    return { min: 5, max: 17, get: birdSpotZoomFrom, key: "birdSpotZoom" };
