    var syncFile = document.getElementById("sync-file");
    document.getElementById("sync-import").addEventListener("click", function () { syncFile.click(); });
    syncFile.addEventListener("change", function (e) {
      var f = e.target.files && e.target.files[0]; if (!f) return;
      var rd = new FileReader();
      rd.onload = function () {
        try {
          var s = importAppData(rd.result);
          setStatus(t("sync.imported", { n: s.checklistsIncoming, total: s.checklistsTotal }));
          setTimeout(function () { location.reload(); }, 1000);
        } catch (err) { setStatus(t("sync.importFailed", { msg: err.message || "" })); }
        e.target.value = "";
      };
      rd.readAsText(f);
    });

    // Google Drive sync controls. The transport lives in window.GDriveSync; here
    // we just reflect its state into the buttons and forward user gestures.
    if (window.GDriveSync) {
      var gdConnect = document.getElementById("gd-connect");
      var gdSync = document.getElementById("gd-sync");
      var gdDisconnect = document.getElementById("gd-disconnect");
      var gdClientId = document.getElementById("gd-clientid");
      var gdStatus = document.getElementById("gd-status");
      try { gdClientId.value = localStorage.getItem("gdrive-client-id") || ""; } catch (e) {}

      var renderGd = function (st) {
        // One-shot: a single "Synchronize" button signs in, syncs, then
        // disconnects — so it's the only control (Connect/Disconnect hidden).
        var needId = !st.hasClientId;
        gdClientId.style.display = needId ? "" : "none";
        gdConnect.style.display = "none";
        gdSync.style.display = needId ? "none" : "";
        gdDisconnect.style.display = "none";
        gdSync.disabled = !!st.busy;
        var msg = "";
        var failed = st.status === "reconnect" || st.status === "error";
        if (st.status === "syncing") msg = "⟳ " + t("gdrive.syncing");
        else if (st.status === "reconnect") msg = "⚠ " + t("gdrive.reconnect");
        else if (st.status === "error") msg = "⚠ " + t("gdrive.error");
        else if (st.lastSyncAt) msg = "✓ " + t("gdrive.synced") + " · " + fmtClock(st.lastSyncAt);
        // Surface the actual failure reason so a sync error isn't silent.
        if (failed && st.error) msg += " · " + st.error;
        gdStatus.textContent = msg;
        gdStatus.title = failed && st.error ? st.error : "";
        gdStatus.classList.toggle("gd-syncing", st.status === "syncing");
        gdStatus.classList.toggle("gd-error", failed);
      };
      window.GDriveSync.onStatus(renderGd);

      // The sync dialog: pick which categories + one global direction, then run.
      // Defaults (all categories, two-way) reproduce the old one-tap behaviour.
      function openSyncDialog() {
        if (document.getElementById("sync-opts-modal")) return;
        var saved = window.GeoState.get("syncOpts", null) || {};
        var dir = saved.direction || "two";
        var cats = saved.cats || { settings: 1, lists: 1, trips: 1, checklists: 1, fetched: 1 };
        var catRow = function (id, lbl) { return '<label class="so-cat"><input type="checkbox" class="so-cat-cb" data-cat="' + id + '"' + (cats[id] ? " checked" : "") + "> " + escapeHtml(t(lbl)) + "</label>"; };
        var dirRow = function (val, lbl) { return '<label class="so-dir"><input type="radio" name="so-dir" value="' + val + '"' + (dir === val ? " checked" : "") + "> " + escapeHtml(t(lbl)) + "</label>"; };
        var ov = document.createElement("div"); ov.id = "sync-opts-modal"; ov.className = "kml-modal";
        ov.innerHTML = '<div class="kml-modal-box sync-opts-box">' +
          '<button type="button" class="kml-close so-close" aria-label="' + escapeHtml(t("btn.close")) + '">×</button>' +
          "<h3>" + escapeHtml(t("sync.title")) + "</h3>" +
          '<div class="so-sec">' + escapeHtml(t("sync.direction")) + "</div>" +
          dirRow("two", "sync.dirTwo") + dirRow("upload", "sync.dirUp") + dirRow("download", "sync.dirDown") +
          '<div class="so-sec">' + escapeHtml(t("sync.include")) + "</div>" +
          catRow("settings", "sync.catSettings") + catRow("lists", "sync.catLists") + catRow("trips", "sync.catTrips") + catRow("checklists", "sync.catChecklists") + catRow("fetched", "sync.catFetched") +
          '<p class="cu-hint">' + escapeHtml(t("sync.mergeNote")) + "</p>" +
          '<div class="so-actions"><button type="button" class="btn btn-light so-cancel">' + escapeHtml(t("btn.cancel")) + '</button><button type="button" class="btn so-go">' + escapeHtml(t("gdrive.syncNow")) + "</button></div>" +
          "</div>";
        document.body.appendChild(ov);
        var close = function () { if (ov.parentNode) ov.parentNode.removeChild(ov); };
        ov.addEventListener("click", function (e) { if (e.target === ov) close(); });
        ov.querySelector(".so-close").addEventListener("click", close);
        ov.querySelector(".so-cancel").addEventListener("click", close);
        ov.querySelector(".so-go").addEventListener("click", function () {
          var chosenDir = (ov.querySelector('input[name="so-dir"]:checked') || {}).value || "two";
          var chosenCats = {};
          Array.prototype.forEach.call(ov.querySelectorAll(".so-cat-cb"), function (cb) { chosenCats[cb.getAttribute("data-cat")] = cb.checked ? 1 : 0; });
          window.GeoState.save({ syncOpts: { direction: chosenDir, cats: chosenCats } });
          close();
          gdStatus.textContent = "⟳ " + t("gdrive.syncing"); gdStatus.classList.add("gd-syncing");
          window.GDriveSync.syncNow({ direction: chosenDir, cats: chosenCats });
        });
      }
      gdConnect.addEventListener("click", function () { window.GDriveSync.connect().catch(function () {}); });
      gdSync.addEventListener("click", openSyncDialog);
      gdDisconnect.addEventListener("click", function () { window.GDriveSync.disconnect(); });
      var saveClientId = function () { window.GDriveSync.setClientId(gdClientId.value); };
      gdClientId.addEventListener("change", saveClientId);
    }

