        try { map.fitBounds([[l.lat - dLat, l.lon - dLon], [l.lat + dLat, l.lon + dLon]], { padding: [20, 20] }); }
        catch (e) { map.setView([l.lat, l.lon], Math.max(map.getZoom() || 0, 13)); }
        selectMapPoint(l.lat, l.lon, true);
