    recentRadiusKm: recentRadiusKm, safeHref: safeHref, setStatus: setStatus,
    setTabAlert: setTabAlert, showDetHover: showDetHover,
    spDetailTableHtml: spDetailTableHtml, spListDot: spListDot,
